import {e} from './ui.mjs?v=20261119privacyindex';
export function privacyEditor(d,{input,block}){
 return block('Aviso de privacidad','<p>Edita el aviso completo y los datos que se muestran junto a los formularios. Guarda y usa Vista previa antes de Publicar. Los cambios publicados tendrán su propia versión para registrar las autorizaciones.</p>'+input('privacy.title','Título')+input('privacy.eyebrow','Texto superior')+input('privacy.updated','Fecha de actualización',{type:'date'}))+
 block('Permisos de fotos y testimonios','<p>Conserva la confirmación de las personas en un expediente privado. El permiso para promocionar un inmueble no se presume equivalente al uso de fotos personales o testimonios.</p><a class="text-link" href="assets/confirmacion-imagen-testimonio.txt" target="_blank" rel="noopener" download>Descargar modelo de confirmación</a>')+
 block('Responsable y contacto',input('privacy.responsibleName','Nombre del responsable')+input('privacy.brand','Nombre comercial')+input('privacy.address','Domicilio',{area:true})+input('privacy.email','Correo para privacidad y derechos ARCO',{type:'email'}))+
 block('Información junto a los formularios',input('privacy.contactPurpose','Finalidad del formulario de contacto',{area:true})+input('privacy.reviewPurpose','Finalidad del formulario de reseñas',{area:true})+input('privacy.summaryEnding','Texto adicional del aviso breve',{area:true}))+
 d.privacy.sections.map((s,i)=>block(s.title,input(`privacy.sections.${i}.title`,'Título del apartado')+input(`privacy.sections.${i}.body`,'Texto · separa párrafos con una línea vacía; usa - para una lista',{area:true})+s.links.map((l,j)=>`<details class="editor-item"><summary>${e(l.label)}</summary>${input(`privacy.sections.${i}.links.${j}.label`,'Texto del enlace')+input(`privacy.sections.${i}.links.${j}.href`,'Enlace HTTPS o mailto:')}<button type="button" class="text-button danger" data-remove-privacy-link="${i},${j}">Eliminar enlace</button></details>`).join('')+`<button type="button" class="button button-outline" data-add-privacy-link="${i}" ${s.links.length>=10?'disabled':''}>Agregar enlace</button>`)).join('')+
 block('Contacto al final del aviso',input('privacy.contactHeading','Texto')+input('privacy.contactButton','Texto del botón de correo'));
}
